head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > drilldownToggle]<br/>inputType='drilldown' 인 Body Column 에서 Enter 키 입력 시 토글을 실행할지 설정합니다.",
    "validation" : [
        "'' (빈 문자열) 설정 시, Enter 키 입력 시 enterKeyMove, focusMove 속성값에 맞게 포커스를 이동시킵니다.",
        "미설정 시, Enter 키 입력 시 enterKeyMove, focusMove 속성값에 맞게 포커스를 이동시킵니다.",
        "'enter' 설정 시, Enter 키 입력 시 해당 Row 의 펼침 상태를 토글합니다.",
        "inputType='drilldown' 인 Body Cell 포커스가 한 개 있을때만 토글이 실행됩니다.",
        "Enter 키로 Row 의 펼침 상태가 변경되면 onbeforetoggleclick 이벤트 없이 ontoggleclick 가 바로 발생합니다."
    ]
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성 (비동기 dynamicCreate 완료까지 대기)
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 (Target 재생성 버튼 클릭 시 재실행)
//  - inputType="drilldown" 트리 컬럼 + depth(계층) 데이터로 DrillDown 그리드 구성
//    · 부모 Row(자식 있음 → 토글 버튼 표시) : "영업본부"(idx0), "개발본부"(idx2)
//    · 자식 Row : "영업1팀"(idx1), "개발1팀"(idx3)
//    · Leaf Row(자식 없음) : "관리팀(독립)"(idx4, depth1)
//  - con_drilldownToggle : 미설정('') / enter
//    · 미설정('') : Enter 키 입력 시 토글 없이 enterKeyMove/focusMove 로 포커스 이동
//    · enter      : drilldown 셀에 단일 포커스가 있을 때 Enter 키로 해당 Row 펼침 상태 토글
//  - onbeforetoggleclick / ontoggleclick 을 함께 바인딩 → Enter 토글 시 onbeforetoggleclick 없이 ontoggleclick 만 발생(@spec2) vs 실제 +/- 아이콘 클릭 시 둘 다 발생
scwin.comp_init = async function () {
    // 기존 target / dataList 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();

    // 현재 con 적용값 (미설정이면 빈 문자열 → 속성 자체 미설정 = 엔진 기본)
    //  - drilldownToggle 은 자체 값('' / 'enter') selectbox 라 getValue()
    let cToggle = con_drilldownToggle.getValue();

    // 안내 라벨 (target 생성 전 가장 먼저 생성)
    //  - 셀 포커스/Enter 는 사용자 액션이므로 라벨로 조작 방법 안내
    $c.gcm.createLabel('label="[전제] inputType=drilldown 트리 그리드(초기 접힘, 최상위 영업본부/개발본부/관리팀만 표시). 부모(영업본부 idx0 / 개발본부 idx2)는 자식 보유, 관리팀(idx4)은 Leaf. con_drilldownToggle=(현재 [' + (cToggle === '' ? '미설정' : cToggle) + ']). con 변경은 Target 재생성 버튼으로 반영.\n[절차] 부모 Row 의 drilldown 셀(텍스트 영역)을 클릭해 단일 포커스를 준 뒤 Enter 키를 입력.\n[확인] enter=해당 Row 토글(자식 펼침/접힘) + ontoggleclick 만 발생(onbeforetoggleclick 미발생). 미설정=토글 없이 포커스 이동(ontoggleclick 미발생). 실제 +/- 아이콘 좌클릭 토글은 onbeforetoggleclick+ontoggleclick 둘 다 발생(대조)."', '', 'label1');

    // === 바인딩 DataList(dlt_bind) ===
    //  - depth : 계층 깊이(number). drilldown 컬럼의 depthColumn 으로 사용 (부모=1, 자식=2)
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="amount" name="amount" dataType="number"></w2:column>';
    strDlt += '<w2:column id="depth" name="depth" dataType="number"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    // 계층 데이터 : 부모(depth1) > 자식(depth2). 부모 바로 아래 자식 위치(엔진 drilldown 은 순서 기반)
    //  - idx0 영업본부(부모) > idx1 영업1팀(자식)
    //  - idx2 개발본부(부모) > idx3 개발1팀(자식)
    //  - idx4 관리팀(독립, depth1, 자식 없음) → Leaf
    let jsonData = [
        { "name": "영업본부",     "amount": 100, "depth": 1 },
        { "name": "영업1팀",      "amount": 110, "depth": 2 },
        { "name": "개발본부",     "amount": 200, "depth": 1 },
        { "name": "개발1팀",      "amount": 210, "depth": 2 },
        { "name": "관리팀(독립)", "amount": 300, "depth": 1 }
    ];
    dlt_bind.setJSON(jsonData, false);

    // con 속성 문자열 (미설정이면 속성 자체를 넣지 않음 = 엔진 기본값)
    let strAttr = '';
    if (cToggle !== '') {
        strAttr += ' drilldownToggle="' + cToggle + '"';
    }

    // target 그리드 직접 구성 (DrillDown 트리 컬럼)
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + strAttr + ' dataList="data:dlt_bind" rowNumVisible="true" ev:onkeydown="scwin.target1_onkeydown" ev:onbeforetoggleclick="scwin.target1_onbeforetoggleclick" ev:ontoggleclick="scwin.target1_ontoggleclick" id="" style="width:560px;height:300px;">';
    strTarget += '<w2:caption style="" id="caption1" value="drilldownToggle (Enter 토글) 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="320" style="" inputType="text" id="hcol1" value="조직(drilldown)"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol2" value="금액"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="320" style="" inputType="drilldown" depthColumn="depth" showDepth="1" depthStartIndex="1" id="name" dataList="name"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" dataType="number" displayFormat="#,###" id="amount" dataList="amount"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
};



// onbeforetoggleclick : 토글 동작 직전 발생.
//  - 실제 +/- 아이콘 좌클릭 토글 경로에서만 발생. Enter 키 토글(toggle 메소드 경로)에서는 발생하지 않음(@spec2 검증).
scwin.target1_onbeforetoggleclick = function (rowIndex) {
    wf_body_bottom.getObj("scwin").setReturnValue("▶ onbeforetoggleclick rowIndex : " + rowIndex);
};



// ontoggleclick : 토글 상태가 모두 변경된 이후 발생.
//  - drilldownToggle='enter' + drilldown 셀 단일 포커스 + Enter → 이 이벤트만 발생(onbeforetoggleclick 미발생, @spec2)
//  - collapsed : true=자식 Row 접힘 / false=자식 Row 펼쳐짐
//  - rowIndex : 토글된 실제 Row 인덱스
scwin.target1_ontoggleclick = function (collapsed, rowIndex) {
    wf_body_bottom.getObj("scwin").setReturnValue("▶ ontoggleclick collapsed : " + collapsed + ", rowIndex : " + rowIndex);
};



// onkeydown : drilldownToggle 미설정('') 일때 Enter 키 입력 시 토글 대신 포커스가 (enterKeyMove/focusMove 에 맞게) 이동함을 출력에 반영.
//  - Enter 직전 포커스 셀 -> setTimeout 으로 이동 후 포커스 셀을 읽어 (이동 전 -> 이동 후) 를 출력.
//  - drilldownToggle='enter' 이면 토글이 실행(ontoggleclick 출력)되므로 여기서는 출력하지 않는다.
scwin.target1_onkeydown = function (e) {
    if (e.keyCode !== 13) return;                                // Enter 만
    if (target1.options.drilldownToggle === 'enter') return;     // enter 모드는 토글(ontoggleclick 담당)
    let fc = target1.focusedCell && target1.focusedCell[0];
    let before = fc ? ('Row ' + fc.focusedRowIndex + ' / Col ' + fc.focusedColIndex) : '(포커스 없음)';
    setTimeout(function () {
        let fc2 = target1.focusedCell && target1.focusedCell[0];
        let after = fc2 ? ('Row ' + fc2.focusedRowIndex + ' / Col ' + fc2.focusedColIndex) : '(포커스 없음)';
        wf_body_bottom.getObj("scwin").setReturnValue("▶ Enter (drilldownToggle 미설정) -> 포커스 이동 : " + before + " -> " + after + " (토글 없음)");
    }, 0);
};
